text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي",
  "planted": [
    {
      "slot": "p1",
      "text": "تحتفظ شركة الأفق الرقمي بحق استخدام البيانات والمعلومات المجمعة من المستخدمين لأي غرض تراه الإدارة مناسباً لدعم نمو العمل وتحسين تجربة المستخدمين، بما في ذلك الأغراض التشغيلية المستقبلية التي قد يتم استحداثها لاحقاً دون الحاجة لتقديم إشعار مسبق أو الحصول على موافقة إضافية."
    },
    {
      "slot": "p2",
      "text": "باعتبار أن قواعد البيانات الخاصة بالمنصة تشكل أصلاً تجارياً مملوكاً بالكامل للشركة، فإنه لا يحق للمستخدم طلب الاطلاع على السجلات الرقمية الخاصة به أو تعديلها، كما لا تقبل الشركة أي طلبات لحذف أو إتلاف البيانات المحفوظة في خوادمها مهما كانت الظروف."
    },
    {
      "slot": "p3",
      "text": "تعتمد الشركة على سند المصالح المشروعة لمعالجة البيانات الحساسة والبيانات الصحية والبيانات الحيوية للمستخدمين، وتستიد من هذه الفئات لتحليل السلوك الاستهلاكي وتوجيه الحملات الترويجية المخصصة ومشاركة تلك الملفات مع الشركاء التجاريين لضمان فعالية الخدمات المقدمة."
    },
    {
      "slot": "p4",
      "text": "نرسل الرسائل الترويجية والمواد التسويقية فقط بناءً على الموافقة المسبقة والصريحة من المستلم عبر قنوات الاتصال الشخصية الخاصة به، مع توفير آلية واضحة وبسيطة وسهلة الاستخدام لتمكين المستخدم من إيقاف استقبال تلك المواد الإعلانية في أي وقت."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية المتمثلة في الرسوم المقررة لتقديم الخدمات لبوابات الدفع الإلكتروني المعتمدة من قبل الشركة، ويتم خصم المبالغ المستحقة فور تأكيد الطلب.",
    "تبدأ مدة العقد بين الطرفين اعتباراً من تاريخ تفعيل الحساب، ويحق لأي طرف إنهاء التعاقد بموجب إشعار كتابي يرسل قبل موعد الإنهاء بثلاثين يوماً على الأقل دون تحمل غرامات إضافية.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناتجة عن انقطاع الخدمة أو سوء استخدام المنصة من قبل الأطراف الأخرى.",
    "تفسر هذه الشروط وتخضع لأنظمة وقوانين المملكة العربية السعودية، وتختص الجهات القضائية حصرياً بالفصل في أي نزاع قد ينشأ عنها.",
    "تعتبر حقوق الملكية الفكرية لجميع التصاميم والنصوص والعلامات التجارية مسجلة ومحمية بموجب اللوائح التجارية السارية، ولا يجوز نسخها أو إعادة استنساخها دون إذن خطي مسبق."
  ]
}
